import "./comparison-workflow.css";

export interface ComparisonCriterion {
  label: string;
  left: string;
  right: string;
}

export interface ComparisonWorkflowProps {
  title: string;
  leftLabel: string;
  rightLabel: string;
  criteria: ComparisonCriterion[];
}

export function ComparisonWorkflow({
  title,
  leftLabel,
  rightLabel,
  criteria,
}: ComparisonWorkflowProps) {
  return (
    <section className="tb-comparison">
      <h2>{title}</h2>
      <div className="tb-comparison__labels" aria-hidden="true">
        <span />
        <strong>{leftLabel}</strong>
        <strong>{rightLabel}</strong>
      </div>
      <div className="tb-comparison__criteria">
        {criteria.map((criterion) => (
          <article key={criterion.label}>
            <h3>{criterion.label}</h3>
            <div>
              <strong>{leftLabel}</strong>
              <p>{criterion.left}</p>
            </div>
            <div>
              <strong>{rightLabel}</strong>
              <p>{criterion.right}</p>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

.tb-comparison {
  --tb-cw-ink: #f0f2ed;
  --tb-cw-ground: #1d2423;
  --tb-cw-panel: #2c3533;
  --tb-cw-accent: #e7c85a;
  container-type: inline-size;
  padding: clamp(3rem, 6%, 7rem) clamp(1.25rem, 5%, 5.5rem);
  color: var(--tb-cw-ink);
  background: var(--tb-cw-ground);
}

.tb-comparison,
.tb-comparison * {
  box-sizing: border-box;
}

.tb-comparison > h2 {
  max-width: 48rem;
  margin: 0 0 clamp(3rem, 6cqi, 6rem);
  font-size: clamp(2.6rem, 6vw, 5.8rem);
  font-size: clamp(2.6rem, 7cqi, 5.8rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.025em;
  overflow-wrap: anywhere;
}

.tb-comparison__labels,
.tb-comparison__criteria article {
  display: grid;
  grid-template-columns: minmax(8rem, 0.55fr) minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(1.25rem, 3cqi, 3.5rem);
}

.tb-comparison__labels {
  padding: 0 1.25rem 1rem;
  color: var(--tb-cw-accent);
  font-size: 0.86rem;
}

.tb-comparison__criteria {
  display: grid;
  gap: 0.65rem;
}

.tb-comparison__criteria article {
  align-items: start;
  padding: clamp(1.5rem, 3cqi, 2.75rem) 1.25rem;
  background: var(--tb-cw-panel);
}

.tb-comparison__criteria article:nth-child(even) {
  background: #343d3b;
}

.tb-comparison__criteria h3 {
  margin: 0;
  font-size: clamp(1.15rem, 2.5cqi, 1.55rem);
  overflow-wrap: anywhere;
}

.tb-comparison__criteria p {
  max-width: 34rem;
  margin: 0;
  color: #d0d6d2;
  line-height: 1.55;
  overflow-wrap: anywhere;
}

.tb-comparison__criteria div > strong {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  color: var(--tb-cw-accent);
  font-size: 0.8rem;
}

@container (max-width: 48rem) {
  .tb-comparison__labels {
    display: none;
  }

  .tb-comparison__criteria article {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .tb-comparison__criteria div > strong {
    position: static;
    width: auto;
    height: auto;
    overflow: visible;
    clip: auto;
    clip-path: none;
    white-space: normal;
    display: block;
    margin-bottom: 0.45rem;
  }
}

@media (max-width: 760px) {
  .tb-comparison__labels {
    display: none;
  }

  .tb-comparison__criteria article {
    grid-template-columns: 1fr;
  }

  .tb-comparison__criteria div > strong {
    position: static;
    width: auto;
    height: auto;
    overflow: visible;
    clip: auto;
    clip-path: none;
    white-space: normal;
    display: block;
    margin-bottom: 0.45rem;
  }
}
